"""Build the final HTML report from computed metrics and charts."""
import json, pandas as pd, numpy as np

with open("/tmp/nke_metrics.json") as f:
    data = json.load(f)
with open("/tmp/nke_charts.json") as f:
    charts = json.load(f)

m = data["metrics"]
decades = data["decade_stats"]
episodes = data["episodes"]
top_vol = data["top_vol"]
vol_eras = data["vol_eras"]

annual = pd.read_pickle("/tmp/nke_annual.pkl")
df = pd.read_pickle("/tmp/nke_df.pkl")

best_year = annual.loc[annual["YearReturn"].idxmax()]
worst_year = annual.loc[annual["YearReturn"].idxmin()]
positive_years = (annual["YearReturn"] >= 0).sum()
total_years = len(annual)

# Build annual table rows
annual_rows = ""
for _, r in annual.iterrows():
    yr = int(r["Year"])
    ret = r["YearReturn"] * 100
    color = "#059669" if ret >= 0 else "#DC2626"
    annual_rows += f"""<tr>
        <td>{yr}</td>
        <td>${r['YearOpen']:.2f}</td>
        <td>${r['YearClose']:.2f}</td>
        <td>${r['YearHigh']:.2f}</td>
        <td>${r['YearLow']:.2f}</td>
        <td style="color:{color};font-weight:600;">{ret:+.1f}%</td>
        <td>{r['AnnVol']*100:.1f}%</td>
        <td>{r['AvgVolume']/1e6:.1f}M</td>
    </tr>"""

# Decade table rows
decade_rows = ""
for d in decades:
    ret = d["total_return"] * 100
    color = "#059669" if ret >= 0 else "#DC2626"
    decade_rows += f"""<tr>
        <td>{d['decade']}</td>
        <td>${d['start_price']:.2f}</td>
        <td>${d['end_price']:.2f}</td>
        <td style="color:{color};font-weight:600;">{ret:+.1f}%</td>
        <td>{d['cagr']*100:.1f}%</td>
        <td>{d['ann_vol']*100:.1f}%</td>
        <td>{d['max_dd']*100:.1f}%</td>
        <td>{d['avg_volume']/1e6:.1f}M</td>
    </tr>"""

# Drawdown episodes table
dd_rows = ""
for i, e in enumerate(episodes):
    dd_rows += f"""<tr>
        <td>{i+1}</td>
        <td>{e['start']}</td>
        <td>{e['trough_date']}</td>
        <td>{e['end']}</td>
        <td style="color:#DC2626;font-weight:600;">{e['max_dd']*100:.1f}%</td>
        <td>{e['duration_days']} days</td>
    </tr>"""

# Top volume days
topvol_rows = ""
for v in top_vol:
    ret = v.get("DailyReturn", 0)
    if ret and not (isinstance(ret, float) and np.isnan(ret)):
        ret_str = f"{ret*100:+.1f}%"
        color = "#059669" if ret >= 0 else "#DC2626"
    else:
        ret_str = "N/A"
        color = "#6B7280"
    topvol_rows += f"""<tr>
        <td>{v['Date'][:10]}</td>
        <td>{v['Volume']/1e6:.1f}M</td>
        <td>${v['Close']:.2f}</td>
        <td style="color:{color};">{ret_str}</td>
    </tr>"""

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) — Historical Stock Performance Analysis (2000–2026)</title>
<style>
  :root {{
    --primary: #1E3A5F;
    --accent: #2563EB;
    --positive: #059669;
    --negative: #DC2626;
    --bg: #FFFFFF;
    --surface: #F8FAFC;
    --border: #E2E8F0;
    --text: #1E293B;
    --text-muted: #64748B;
    --text-light: #94A3B8;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    color: var(--text);
    background: var(--bg);
    line-height: 1.7;
    font-size: 15px;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 40px 24px; }}

  /* Header */
  .report-header {{
    border-bottom: 3px solid var(--primary);
    padding-bottom: 24px;
    margin-bottom: 40px;
  }}
  .report-header h1 {{
    font-size: 28px;
    color: var(--primary);
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 6px;
  }}
  .report-header .subtitle {{
    font-size: 16px;
    color: var(--text-muted);
    font-weight: 400;
  }}
  .report-header .meta {{
    margin-top: 12px;
    font-size: 13px;
    color: var(--text-light);
  }}

  /* KPI Dashboard */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin: 24px 0 40px 0;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
    text-align: center;
  }}
  .kpi-card .kpi-label {{
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--text-muted);
    font-weight: 600;
    margin-bottom: 6px;
  }}
  .kpi-card .kpi-value {{
    font-size: 28px;
    font-weight: 700;
    color: var(--primary);
    line-height: 1.2;
  }}
  .kpi-card .kpi-sub {{
    font-size: 12px;
    color: var(--text-light);
    margin-top: 4px;
  }}
  .kpi-card.positive .kpi-value {{ color: var(--positive); }}
  .kpi-card.negative .kpi-value {{ color: var(--negative); }}

  /* Sections */
  .section {{
    margin-bottom: 48px;
  }}
  .section h2 {{
    font-size: 22px;
    color: var(--primary);
    font-weight: 700;
    border-bottom: 2px solid var(--border);
    padding-bottom: 8px;
    margin-bottom: 20px;
  }}
  .section h3 {{
    font-size: 17px;
    color: var(--primary);
    font-weight: 600;
    margin: 24px 0 12px 0;
  }}
  .section p {{
    margin-bottom: 14px;
    color: var(--text);
  }}

  /* Charts */
  .chart-container {{
    margin: 20px 0;
    text-align: center;
  }}
  .chart-container img {{
    max-width: 100%;
    height: auto;
    border: 1px solid var(--border);
    border-radius: 8px;
  }}

  /* Tables */
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin: 16px 0;
  }}
  thead th {{
    background: var(--primary);
    color: #fff;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }}
  tbody td {{
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
  }}
  tbody tr:nth-child(even) {{ background: #F8FAFC; }}
  tbody tr:hover {{ background: #EEF2FF; }}

  /* Callout boxes */
  .callout {{
    background: #EFF6FF;
    border-left: 4px solid var(--accent);
    padding: 16px 20px;
    border-radius: 0 8px 8px 0;
    margin: 20px 0;
    font-size: 14px;
  }}
  .callout.warning {{
    background: #FEF2F2;
    border-left-color: var(--negative);
  }}
  .callout.success {{
    background: #ECFDF5;
    border-left-color: var(--positive);
  }}
  .callout strong {{ color: var(--primary); }}

  /* Footer */
  .report-footer {{
    margin-top: 48px;
    padding-top: 20px;
    border-top: 2px solid var(--border);
    font-size: 12px;
    color: var(--text-light);
    text-align: center;
  }}

  /* Responsive */
  @media (max-width: 768px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .container {{ padding: 20px 12px; }}
    table {{ font-size: 11px; }}
  }}
</style>
</head>
<body>
<div class="container">

<!-- ==================== HEADER ==================== -->
<div class="report-header">
  <h1>Nike Inc. (NKE)</h1>
  <div class="subtitle">Historical Stock Performance Analysis &mdash; January 2000 to January 2026</div>
  <div class="meta">
    Data Period: {m['first_date']} to {m['last_date']} &bull; {m['n_rows']:,} trading days &bull;
    Prices are split-adjusted &bull; Source: Kaggle/NKE Historical Data
  </div>
</div>

<!-- ==================== EXECUTIVE SUMMARY ==================== -->
<div class="section" id="executive-summary">
  <h2>Executive Summary</h2>
  <p>
    Over a 26-year span from January 2000 to January 2026, Nike Inc. (NKE) delivered a <strong>cumulative return of {m['cumulative_return']*100:.0f}%</strong>
    (approximately a <strong>{m['cumulative_return']+1:.1f}x</strong> multiple on invested capital), translating to a
    <strong>compound annual growth rate (CAGR) of {m['cagr']*100:.1f}%</strong>. An investor who purchased $10,000 of NKE on {m['first_date']}
    would hold approximately <strong>${10000 * (1 + m['cumulative_return']):,.0f}</strong> by {m['last_date']}.
  </p>
  <p>
    The stock reached its <strong>all-time high of ${m['ath_price']:.2f}</strong> on {m['ath_date']}. However, from that peak the stock
    experienced its <strong>largest drawdown of {m['max_dd']*100:.1f}%</strong>, falling to ${m['trough_price']:.2f} by {m['max_dd_date']} —
    a decline that erased over a decade of gains. Annualized volatility over the full period was <strong>{m['ann_vol']*100:.1f}%</strong>,
    placing NKE in the higher-volatility tier for large-cap consumer stocks.
  </p>
  <p>
    Nike's price history breaks into distinct phases: a deep decline in 2000 followed by a slow recovery through the mid-2000s, a sustained
    secular bull run from ~2009 to late 2021, and a sharp correction from late 2021 through the end of the dataset. Despite the recent drawdown,
    the long-term compounding record remains strong for patient holders who entered at earlier price levels.
  </p>
</div>

<!-- ==================== KPI DASHBOARD ==================== -->
<div class="section">
  <h2>Key Performance Indicators</h2>
  <div class="kpi-grid">
    <div class="kpi-card positive">
      <div class="kpi-label">Cumulative Return</div>
      <div class="kpi-value">{m['cumulative_return']*100:,.0f}%</div>
      <div class="kpi-sub">{m['first_date']} → {m['last_date']}</div>
    </div>
    <div class="kpi-card positive">
      <div class="kpi-label">CAGR</div>
      <div class="kpi-value">{m['cagr']*100:.1f}%</div>
      <div class="kpi-sub">Annualized over {m['years']:.1f} years</div>
    </div>
    <div class="kpi-card negative">
      <div class="kpi-label">Maximum Drawdown</div>
      <div class="kpi-value">{m['max_dd']*100:.1f}%</div>
      <div class="kpi-sub">Peak: {m['peak_before_dd']} → Trough: {m['max_dd_date']}</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Annualized Volatility</div>
      <div class="kpi-value">{m['ann_vol']*100:.1f}%</div>
      <div class="kpi-sub">Daily returns × √252</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Avg Daily Volume</div>
      <div class="kpi-value">{m['avg_volume']/1e6:.1f}M</div>
      <div class="kpi-sub">Shares per trading day</div>
    </div>
  </div>
</div>

<!-- ==================== PRICE TREND ANALYSIS ==================== -->
<div class="section" id="price-trend-analysis">
  <h2>Long-Term Price Trend Analysis</h2>
  <p>
    Nike's 26-year price chart tells a story of extraordinary long-term compounding punctuated by two major drawdowns. The chart below shows
    the split-adjusted closing price alongside 50-day and 200-day moving averages.
  </p>
  <div class="chart-container">
    <img src="{charts['price_trend']}" alt="NKE Price Trend 2000-2026">
  </div>

  <h3>Phase I: The Early-2000s Decline (2000–2002)</h3>
  <p>
    NKE entered the dataset at approximately ${m['first_close']:.2f} (split-adjusted) in January 2000 and quickly plunged to an
    <strong>all-time low of ${m['atl_price']:.2f}</strong> on {m['atl_date']} — a decline of roughly {((m['atl_price']/m['first_close'])-1)*100:.0f}% in under
    two months. This corresponded with the broader dot-com bust and Nike-specific headwinds. The stock remained depressed through much of 2000–2002,
    trading below $5 for extended periods.
  </p>

  <h3>Phase II: Recovery and Steady Growth (2003–2008)</h3>
  <p>
    From the 2000–2002 lows, Nike entered a sustained recovery. The stock climbed steadily through the mid-2000s, benefiting from strong brand momentum
    and international expansion. By late 2007, NKE was trading in the $15–$17 range — a more than 5x recovery from the early-decade trough. The
    2008 Global Financial Crisis interrupted this run, pulling the stock back to the ~$9–$10 area, but the drawdown was comparatively contained
    relative to the broader market.
  </p>

  <h3>Phase III: The Secular Bull Run (2009–2021)</h3>
  <p>
    Post-GFC marked the beginning of Nike's most powerful growth phase. Fueled by the Direct-to-Consumer (DTC) transformation, digital strategy
    acceleration, and global athletic wear tailwinds, NKE compounded relentlessly for over a decade. The stock broke $50 in 2018, $100 in 2020,
    and reached its <strong>all-time high of ${m['ath_price']:.2f} on {m['ath_date']}</strong>. This 12-year run delivered roughly a 16x return from the GFC lows.
  </p>

  <h3>Phase IV: The Post-Peak Correction (2021–2026)</h3>
  <p>
    Following the November 2021 peak, NKE entered a protracted decline that accelerated through 2024 and into 2025. By {m['max_dd_date']},
    the stock had fallen to ${m['trough_price']:.2f} — a <strong>{m['max_dd']*100:.1f}% peak-to-trough drawdown</strong>, the deepest in the dataset.
    This correction reflected multiple headwinds: increased competition, DTC strategy recalibration, inventory challenges, and a
    rotation away from pandemic-era consumer discretionary winners. As of {m['last_date']}, NKE closed at <strong>${m['last_close']:.2f}</strong>,
    still well below its all-time high.
  </p>

  <div class="callout warning">
    <strong>Key Observation:</strong> The 2021–2025 drawdown of {m['max_dd']*100:.1f}% is the largest in Nike's 26-year history in this dataset,
    exceeding even the early-2000s decline and the 2008 GFC pullback. This underscores the valuation risk inherent in buying at peak multiples.
  </div>

  <h3>Logarithmic View</h3>
  <p>
    The log-scale chart below more clearly reveals the compounding character of the returns and the proportional magnitude of drawdowns
    across different price levels.
  </p>
  <div class="chart-container">
    <img src="{charts['price_log']}" alt="NKE Price — Log Scale">
  </div>
</div>

<!-- ==================== VOLATILITY & RISK ==================== -->
<div class="section" id="volatility-analysis">
  <h2>Volatility and Risk Assessment</h2>
  <p>
    Nike's annualized volatility over the full period stands at <strong>{m['ann_vol']*100:.1f}%</strong>, meaningfully above the ~15–20% range
    typical of large-cap consumer staples but in line with higher-beta consumer discretionary names. Volatility has not been constant — it has
    clustered around major market dislocations and company-specific events.
  </p>
  <div class="chart-container">
    <img src="{charts['volatility']}" alt="Rolling Volatility">
  </div>
  <p>
    The 30-day rolling volatility (blue) captures short-term spikes, while the 252-day measure (orange) reveals the structural volatility regime.
    Major spikes are visible during:
  </p>
  <ul style="margin: 0 0 16px 24px;">
    <li><strong>Early 2000:</strong> Extreme 30-day volatility exceeding 80% during the rapid sell-off</li>
    <li><strong>2008–2009:</strong> Elevated volatility through the financial crisis, with 30-day readings above 50%</li>
    <li><strong>March 2020:</strong> COVID-19 shock produced a sharp volatility spike</li>
    <li><strong>2024–2025:</strong> Sustained elevated volatility during the ongoing correction</li>
  </ul>

  <h3>Intraday Range</h3>
  <p>The 30-day average intraday range (High–Low as a percentage of Close) confirms the same volatility clustering pattern.</p>
  <div class="chart-container">
    <img src="{charts['daily_range']}" alt="Daily Price Range">
  </div>

  <h3>Drawdown Analysis</h3>
  <p>The chart below visualizes the depth and duration of all drawdown episodes. Extended periods at deep drawdown levels indicate slow recoveries.</p>
  <div class="chart-container">
    <img src="{charts['drawdown']}" alt="Drawdown from Peak">
  </div>

  <h3>Top 5 Drawdown Episodes</h3>
  <table>
    <thead>
      <tr><th>#</th><th>Start</th><th>Trough</th><th>End</th><th>Max Drawdown</th><th>Duration</th></tr>
    </thead>
    <tbody>
      {dd_rows}
    </tbody>
  </table>
</div>

<!-- ==================== VOLUME ANALYSIS ==================== -->
<div class="section" id="volume-analysis">
  <h2>Trading Volume Patterns</h2>
  <p>
    Average daily trading volume across the full period was <strong>{m['avg_volume']/1e6:.1f} million shares</strong>.
    Volume patterns have evolved significantly over time, both due to structural market changes (decimalization, algorithmic trading)
    and Nike-specific catalysts.
  </p>
  <div class="chart-container">
    <img src="{charts['volume_price']}" alt="Volume vs Price">
  </div>
  <p>
    The overlay chart reveals several key patterns:
  </p>
  <ul style="margin: 0 0 16px 24px;">
    <li><strong>Volume-price correlation during sell-offs:</strong> The sharpest volume spikes coincide with rapid price declines —
      notably early 2000, 2008, and the 2024–2025 correction — indicating capitulation-type selling.</li>
    <li><strong>Secular volume trends:</strong> Volume was elevated in the early 2000s, moderated during the steady mid-2010s advance,
      and rose again during the post-2021 volatility.</li>
    <li><strong>Breakout confirmation:</strong> The transition from accumulation to advance in 2009–2010 was accompanied by
      rising volume, lending technical credibility to the bull phase.</li>
  </ul>

  <h3>Volume by Era</h3>
  <table>
    <thead>
      <tr><th>Era</th><th>Avg Daily Volume</th><th>Median Daily Volume</th><th>Peak Day Volume</th></tr>
